const ACCEPTED_EXTENSIONS = ['jpg', 'jpeg', 'png'];

for (const item of $input.all()) {
  const imageUrl = item.json.imagem_url;

  if (!imageUrl || typeof imageUrl !== 'string') {
    item.json.imagem_url_converted = null;
    continue;
  }

  // Separa URL base e query string
  const [baseUrl, queryString] = imageUrl.split('?');

  // Separa partes pelo ponto
  const parts = baseUrl.split('.');

  if (parts.length < 2) {
    // URL sem extensão clara
    item.json.imagem_url_converted = imageUrl;
    continue;
  }

  const currentExtension = parts.pop().toLowerCase();

  if (ACCEPTED_EXTENSIONS.includes(currentExtension)) {
    // Já é um formato aceito pelo WhatsApp
    item.json.imagem_url_converted = imageUrl;
  } else {
    // Força JPG
    const newBaseUrl = [...parts, 'jpg'].join('.');
    item.json.imagem_url_converted = queryString
      ? `${newBaseUrl}?${queryString}`
      : newBaseUrl;
  }
}

return $input.all();

