const text =
  $json.body?.message ||
  $json.message ||
  $json.text ||
  '';

// Regex genérica para URLs
const urlRegex = /(https?:\/\/[^\s]+)/g;
const urls = text.match(urlRegex);

// Se não tiver URL
if (!urls || urls.length === 0) {
  return [
    {
      json: {
        hasUrl: false,
        cupom: null,
        desconto: null
      }
    }
  ];
}

// Domínios permitidos (afiliados)
const allowedPatterns = [
  /^https?:\/\/(www\.)?amzn\.to\/.+/i,
  /^https?:\/\/(www\.)?meli\.la\/.+/i,
  /^https?:\/\/(www\.)?mercadolivre\.com\/sec\/.+/i,
  /^https?:\/\/(www\.)?amazon\.com\.br\/dp\/[A-Z0-9]+/i
];

// Procura URL válida
const validUrl = urls.find(url =>
  allowedPatterns.some(pattern => pattern.test(url))
);

// 🔎 Detectar CUPOM
let cupom = null;

const cupomRegex = /\b(?:cupom|codigo|código)\s*:?\s*([a-z0-9\-]+)/i;
const cupomMatch = text.match(cupomRegex);

if (cupomMatch && cupomMatch[1]) {
  cupom = cupomMatch[1].toUpperCase();
}

// 🔎 Detectar DESCONTO
let desconto = null;

// primeiro tenta percentual
const percentMatch = text.match(/(\d+(?:[.,]\d+)?)\s*%/);

if (percentMatch) {
  desconto = percentMatch[1] + "%";
} else {
  // tenta número solto (ex: "desconto 12")
  const numberMatch = text.match(/\b(?:desconto|off|descontar|desc)\s*(\d+(?:[.,]\d+)?)/i);
  if (numberMatch) {
    desconto = parseFloat(numberMatch[1].replace(",", "."));
  }
}

// Se não tiver URL válida
if (!validUrl) {
  return [
    {
      json: {
        hasUrl: false,
        cupom,
        desconto
      }
    }
  ];
}

// Retorno final
return [
  {
    json: {
      hasUrl: true,
      url: validUrl,
      cupom,
      desconto
    }
  }
];

function parseMoney(value) {
	if (!value) return 0;
	return parseFloat(
		value
			.toString()
			.replace("R$", "")
			.replace(/\./g, "")
			.replace(",", ".")
			.trim()
	);
}

function formatBRL(value) {
	return "R$ " + value
		.toFixed(2)
		.replace(".", ",")
		.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

const descontoRaw = $('Montar JSON').first().json.desconto;

for (const item of $input.all()) {
	const precoStr = item.json.preco_atual;
	const preco = parseMoney(precoStr);

	let novoPreco = preco;

	if (descontoRaw !== undefined && descontoRaw !== null && descontoRaw !== "") {

		let isPercent = false;
		let valorDesconto = 0;

		// 🔥 Se for STRING
		if (typeof descontoRaw === "string") {
			const desc = descontoRaw.trim();

			if (desc.includes("%")) {
				isPercent = true;
				valorDesconto = parseFloat(desc.replace("%", "").replace(",", "."));
			} else {
				valorDesconto = parseFloat(desc.replace(",", "."));
			}
		}

		// 🔥 Se for NUMBER
		else if (typeof descontoRaw === "number") {
			valorDesconto = descontoRaw;
		}

		// aplica regra
		if (!isNaN(valorDesconto)) {
			if (isPercent) {
				novoPreco = preco - (preco * valorDesconto / 100);
			} else {
				novoPreco = preco - valorDesconto;
			}
		}
	}

	if (novoPreco < 0) novoPreco = 0;

	item.json.preco_atual = formatBRL(novoPreco);
}

return $input.all();

